"""Generate licence inventory from installed dependency metadata, not a handwritten list."""
import json,re,shutil,importlib.metadata as md
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/third-party';OUT.mkdir(parents=True,exist_ok=True)
lines=['# Third-party notices (generated)','', 'Generated by `python scripts/notices.py` from package-lock.json, installed npm package metadata and resolved Python distribution metadata. Includes development/test tools. Not a legal compliance certification; inspect referenced full texts before redistribution.', '', 'Tiger data: https://huggingface.co/datasets/Ultralytics/Tiger-pose, repository-stated AGPL-3.0. Full dataset licence, original selected photographs and pose annotations are included in data/source/tiger/. Displayed images are cropped/resized EXIF-free derivatives. See DATASET.md for provenance, limitations and version. Original Wild-ID code licensing remains pending team approval; no dependency code licence is overridden.', '', '## JavaScript packages', '', '| Package | Version | Licence expression (metadata) | Full notice files |','|---|---|---|---|']
lock=json.loads((ROOT/'package-lock.json').read_text())
for path,meta in sorted(lock['packages'].items()):
    if not path:continue
    directory=ROOT/path
    if not directory.exists():continue # optional platform-specific packages not installed
    p=json.loads((directory/'package.json').read_text());name=p.get('name',path);license=p.get('license',meta.get('license','UNDECLARED'))
    if not isinstance(license,str):license=json.dumps(license)
    dest=OUT/re.sub(r'[^a-zA-Z0-9_.-]','_',name);dest.mkdir(exist_ok=True)
    refs=[]
    for f in directory.iterdir():
        if f.is_file() and re.match(r'(?i)^(licen[cs]e|notice|copying)',f.name):
            shutil.copyfile(f,dest/f.name);refs.append(f'[{f.name}](docs/third-party/{dest.name}/{f.name})')
    lines.append(f"| {name} | {p.get('version','?')} | {license} | {'; '.join(refs) or 'No root notice file; consult upstream metadata'} |")
lines+=['','## Python packages','','| Package | Version | Licence expression / classifiers | Full notice files |','|---|---|---|---|']
for req in (ROOT/'requirements.lock.txt').read_text().splitlines():
    if not req or req.startswith('#'):continue
    name,version=req.split('==');d=md.distribution(name);m=d.metadata
    expression=m.get('License-Expression') or '; '.join(c for c in m.get_all('Classifier',[]) if c.startswith('License ::')) or m.get('License') or 'UNDECLARED'
    expression=expression.replace('\n',' ')[:400]
    dest=OUT/('python-'+name);dest.mkdir(exist_ok=True);refs=[]
    for file in d.files or []:
        if '.dist-info/' in str(file) and re.search(r'(?i)(license|notice|copying)',str(file)):
            source=Path(d.locate_file(file))
            if source.is_file():
                target=dest/str(file).split('.dist-info/')[-1].replace('/','_');shutil.copyfile(source,target);refs.append(f'[{target.name}](docs/third-party/{dest.name}/{target.name})')
    lines.append(f"| {name} | {version} | {expression.replace('|','/')} | {'; '.join(refs) or 'No installed notice file; consult upstream metadata'} |")
lines+=['','## Local detector weights and setup artifacts','','- YOLOv8s-World v2 ONNX: https://huggingface.co/Instemic/yolo-world-onnx, commit 7e1d02c9467c32b141df81890737490764776785, exported from Ultralytics 8.4.37. Repository-stated AGPL-3.0; full licence models/tiger-open-vocabulary/LICENSE-AGPL-3.0.txt. Artifact SHA-256, labels, sizes and text-feature derivation in models/tiger-open-vocabulary/manifest.json and MODEL_CARD.md. Preserve copyleft/source/network-service obligations and review corresponding-source completeness before public redistribution/hosting; original project code licence remains pending team approval. No blanket permissive grant.', '- CLIP text encoder used ONLY during explicit setup: Xenova/clip-vit-base-patch32 commit d15189d7028b43f1d3e65039190477f6af591c2a, derived from OpenAI CLIP ViT-B/32 (https://github.com/openai/CLIP, MIT). Full MIT notice models/tiger-open-vocabulary/LICENSE-CLIP-MIT.txt. Quantized encoder is not a runtime dependency/asset; genuine fixed text embeddings are cached locally. No image is sent to a remote classifier.', '- ONNX Runtime 1.31.0 (MIT), flatbuffers 25.12.19 (Apache-2.0) and protobuf 7.36.2 (BSD-3-Clause): full installed notices above. No PyTorch, Ultralytics Python package, transformers, analytics or third-party browser scripts added.', '- tests/fixtures/tiger-camera.y4m is an explicitly labelled fake-camera test fixture converted from a bundled real Tiger-pose photograph with Pillow. Same source/data licence; not wildlife footage, a benchmark negative, or simulated app detections. See tests/fixtures/README.md and scripts/make_camera_fixture.py.']
(ROOT/'THIRD_PARTY_NOTICES.md').write_text('\n'.join(lines)+'\n')
print('Generated notices for installed dependency closure')
